using System.ComponentModel.DataAnnotations;

namespace OrdersService.Models
{
    public class Order
    {
        // generated by sql server
        public int Id { get; set; }

        [Range(1, int.MaxValue, ErrorMessage = "ProductId must be at least 1.")]
        public int ProductId { get; set; }

        [Range(1, int.MaxValue, ErrorMessage = "Quantity must be at least 1.")]
        public int Quantity { get; set; }

        public DateTime DateCreated { get; set; }

        // one of the OrderStatus constants
        public string Status { get; set; } = string.Empty;

        // Idempotency key supplied by the client (or generated server-side).
        // Unique index: submitting the same request twice returns the same order.
        [MaxLength(64)]
        public string? ClientRequestId { get; set; }

        public DateTime? DateUpdated { get; set; }

        // set while Status == CancellationPending
        public DateTime? CancellationRequestedAt { get; set; }
    }
}
